  children {
    text {
      heading_level: 0
      text: "Avis's standard policy charges hourly late fees (three-fourths of the daily rate plus $0.01 per hour on daily/weekend rates) up to an extra day once you pass your 24-hour window, plus up to $15/day if you don't call 1-800-230-4898 to extend (Avis Reservations FAQ; Avis Rental Car Return FAQ). Because 1450 Bloomfield has no drop box, here is how to maximize your chances of getting the extra charges waived as a President's Club member:"
      annotated_ranges {
        start: 190
        end: 197
        text_annotation {
          style {
            type: BOLD
          }
        }
      }
      annotated_ranges {
